def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split pre-release (after '-')
        if '-' in v_no_build:
            version_part, prerelease_part = v_no_build.split('-', 1)
        else:
            version_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        # None means no pre-release (sorts after pre-release)
        # So we return (1,) for no pre-release and (0, ...) for pre-release
        if identifiers is None:
            return (1,)

        # Convert identifiers to comparable tuples
        key_parts = []
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit identifiers: (0, numeric_value)
                key_parts.append((0, int(identifier)))
            else:
                # Non-digit identifiers: (1, string_value)
                key_parts.append((1, identifier))

        return (0, tuple(key_parts))

    def sort_key(v):
        major, minor, patch, prerelease = parse_version(v)
        return (major, minor, patch, prerelease_key(prerelease))

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

